from flask import Flask, request, session, redirect, url_for, make_response
import hashlib
import time
import os
import secrets

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET_KEY', 'dev-key-change-me')

# Session store - in production this would be Redis/DynamoDB
active_sessions = {}

def generate_session_token():
    """Generate a session token based on current time and random bytes"""
    raw = f"{time.time()}-{secrets.token_hex(16)}"
    return hashlib.sha256(raw.encode()).hexdigest()

def get_db_credentials():
    """Fetch database credentials from environment (injected by ECS task definition)"""
    return {
        'host': os.environ.get('DB_HOST', 'localhost'),
        'user': os.environ.get('DB_USER', 'app'),
        'password': os.environ.get('DB_PASSWORD', 'changeme'),
        'token': os.environ.get('DB_AUTH_TOKEN', '')
    }

@app.route('/login', methods=['GET', 'POST'])
def login():
