        username = request.form.get('username')
        password = request.form.get('password')

        # Simplified auth check
        if authenticate(username, password):
            # VULNERABILITY: Session fixation - accepts pre-existing session ID
            # from query parameter or cookie without regeneration
            existing_sid = request.args.get('sid') or request.cookies.get('SESSIONID')

            if existing_sid and existing_sid in active_sessions:
